			name = "Use 'Shortest Path' plugin",
			description = "Draws the shortest path to the assigned house on the map.<br/>" +
					"The plugin 'Shortest Path' needs to be enabled for this to work",
			position = 3
	)
	default boolean useShortestPath()
	{
		return false;
	}

